public SpringWebMvcThymeleafRequestContext(
            final RequestContext requestContext, final HttpServletRequest httpServletRequest) {
        super();
        Validate.notNull(requestContext, "Spring WebMVC RequestContext cannot be null");
        Validate.notNull(httpServletRequest, "HttpServletRequest cannot be null");
        this.requestContext = requestContext;
        this.httpServletRequest = httpServletRequest;
        this.thymeleafRequestDataValueProcessor =
                new SpringWebMvcThymeleafRequestDataValueProcessor(
                        this.requestContext.getRequestDataValueProcessor(), httpServletRequest);
    }

public ThymeleafEvaluationContext(final ApplicationContext applicationContext,
                                      final ConversionService conversionService,
                                      final Collection<Class<?>> allowedClassOverridesForViews) {

        super();

        Validate.notNull(applicationContext, "Application Context cannot be null");
        // ConversionService CAN be null

        this.applicationContext = applicationContext;
        this.allowedClassOverridesForViews =
                (allowedClassOverridesForViews != null && !allowedClassOverridesForViews.isEmpty()) ?
                        Collections.unmodifiableSet(new HashSet<>(allowedClassOverridesForViews)) : Collections.emptySet();

        this.setBeanResolver(new BeanFactoryResolver(applicationContext));
        if (conversionService != null) {
            this.setTypeConverter(new StandardTypeConverter(conversionService));
        }

        final List<PropertyAccessor> propertyAccessors = new ArrayList<>(5);
        propertyAccessors.add(SPELContextPropertyAccessor.INSTANCE);
        propertyAccessors.add(MAP_ACCESSOR_INSTANCE);

        // Depending on whether custom class overrides are allowed, we will establish a custom type locator in order to
        // forbid access to certain dangerous classes in expressions, as well as matching method resolver and property
        // accessor instances.
        final List<MethodResolver> aclMethodResolvers;
        if (!this.allowedClassOverridesForViews.isEmpty()) {
            propertyAccessors.add(new ThymeleafEvaluationContextACLPropertyAccessor(this.allowedClassOverridesForViews));
            this.setTypeLocator(new ThymeleafEvaluationContextACLTypeLocator(this.allowedClassOverridesForViews));
            aclMethodResolvers = Collections.singletonList(new ThymeleafEvaluationContextACLMethodResolver(this.allowedClassOverridesForViews));
        } else {
            propertyAccessors.add(REFLECTIVE_PROPERTY_ACCESSOR_INSTANCE);
            this.setTypeLocator(TYPE_LOCATOR);
            aclMethodResolvers = METHOD_RESOLVERS;
        }
        this.setMethodResolvers(aclMethodResolvers);
        this.setPropertyAccessors(propertyAccessors);

        // Build the SimpleEvaluationContext used in restricted mode: an empty evaluation context. This is because
        // resolution of property accessors and ACL method resolvers will be delegated to the superclass to allow for
        // customization by devs, and at the same time providing no constructor resolution at all, no type
        // references (T(...)) and no bean references (@bean), all of which are already blocked by the
        // expression-level checks but will also be blocked here, at the evaluation-context level.
        this.restrictedModeContext = SimpleEvaluationContext.forPropertyAccessors().build();

    }

public static String computeViewContentType(
            final IWebExchange webExchange, final String defaultContentType, final Charset defaultCharset) {

        if (webExchange == null) {
            throw new IllegalArgumentException("Request cannot be null");
        }


        // First we will check if there is a content type already resolved by Spring's own content negotiation
        // mechanism (see ContentNegotiatingViewResolver, which is autoconfigured in Spring Boot)
        final MediaType negotiatedMediaType = (MediaType) webExchange.getAttributeValue(View.SELECTED_CONTENT_TYPE);
        if (negotiatedMediaType != null && negotiatedMediaType.isConcrete()) {
            final Charset negotiatedCharset = negotiatedMediaType.getCharset();
            if (negotiatedCharset != null) {
                return negotiatedMediaType.toString();
            } else {
                return ContentTypeUtils.combineContentTypeAndCharset(negotiatedMediaType.toString(), defaultCharset);
            }
        }


        // We will apply the default charset here because, after all, we are in an HTTP environment, and
        // the way charset is specified in HTTP is as a parameter in the same Content-Type HTTP header.
        final String combinedContentType =
                ContentTypeUtils.combineContentTypeAndCharset(defaultContentType, defaultCharset);

        // Maybe there is no value for 'defaultValue', but anyway we might want to preserve the charset
        // from the defaultContentType into the viewName-computed one
        final Charset combinedCharset =
                ContentTypeUtils.computeCharsetFromContentType(combinedContentType);

        // If the request path offers clues on the content type that would be more appropriate (because it
        // ends in ".html", ".xml", ".js", etc.), just use it
        final String requestPathContentType =
                ContentTypeUtils.computeContentTypeForRequestPath(webExchange.getRequest().getRequestPath(), combinedCharset);
        if (requestPathContentType != null) {
            return requestPathContentType;
        }

        // No way to determine a better/more specific content-type, so just return the (adequately combined) defaults
        return combinedContentType;

    }

public static void checkViewNameNotInRequest(final String viewName, final IWebRequest request) {

        final String vn = StringUtils.pack(viewName);

        if (!containsExpression(vn)) {
            // We are only worried about expressions coming from user input, so if the view name contains no
            // expression at all, we should be safe at this stage.
            return;
        }

        boolean found = false;

        final String pathWithinApplication =
                StringUtils.pack(UriEscape.unescapeUriPath(request.getPathWithinApplication()));
        if (pathWithinApplication != null && containsExpression(pathWithinApplication)) {
            // View name contains an expression, and it seems the path does too. This is too dangerous.
            found = true;
        }

        if (!found) {
            final Map<String,String[]> parameterMap = request.getParameterMap();
            if (parameterMap != null && !parameterMap.isEmpty()) {
                for (final String[] parameterValues : parameterMap.values()) {
                    if (parameterValues == null) {
                        continue;
                    }
                    for (int i = 0; !found && i < parameterValues.length; i++) {
                        final String parameterValue = StringUtils.pack(parameterValues[i]);
                        if (parameterValue != null && containsExpression(parameterValue) && vn.contains(parameterValue)) {
                            // Request parameter contains an expression, and it is contained in the view name. Too dangerous.
                            found = true;
                        }
                    }
                    if (found) {
                        break;
                    }
                }
            }
        }

        if (!found) {
            final Map<String,String[]> cookieMap = request.getCookieMap();
            if (cookieMap != null && !cookieMap.isEmpty()) {
                for (final String[] cookieValues : cookieMap.values()) {
                    if (cookieValues == null) {
                        continue;
                    }
                    for (int i = 0; !found && i < cookieValues.length; i++) {
                        final String cookieValue = StringUtils.pack(cookieValues[i]);
                        if (cookieValue != null && containsExpression(cookieValue) && vn.contains(cookieValue)) {
                            // Cookie contains an expression, and it is contained in the view name. Too dangerous.
                            found = true;
                        }
                    }
                    if (found) {
                        break;
                    }
                }
            }
        }

        if (!found) {
            final Map<String,String[]> headerMap = request.getHeaderMap();
            if (headerMap != null && !headerMap.isEmpty()) {
                for (final String[] headerValues : headerMap.values()) {
                    if (headerValues == null) {
                        continue;
                    }
                    for (int i = 0; !found && i < headerValues.length; i++) {
                        final String headerValue = StringUtils.pack(headerValues[i]);
                        if (headerValue != null && containsExpression(headerValue) && vn.contains(headerValue)) {
                            // Header contains an expression, and it is contained in the view name. Too dangerous.
                            found = true;
                        }
                    }
                    if (found) {
                        break;
                    }
                }
            }
        }

        if (found) {
            throw new TemplateProcessingException(
                    "View name contains an expression and so does either the URL path or the request parameters " +
                    "or contents. This is forbidden in order to reduce the possibilities that direct user input " +
                    "is executed as a part of the view name.");
        }

    }

public WebExpressionContext(
            final IEngineConfiguration configuration,
            final IWebExchange webExchange,
            final Locale locale, final Map<String, Object> variables) {
        super(configuration, locale, variables);
        Validate.notNull(webExchange, "Web exchange cannot be null in web context");
        this.webExchange = webExchange;
    }

public static ExecutedFragmentExpression createExecutedFragmentExpression(
            final IExpressionContext context, final FragmentExpression expression) {
        // All FragmentExpressions will be executed as RESTRICTED (no URL parameters allowed)
        return doCreateExecutedFragmentExpression(context, expression, StandardExpressionExecutionContext.RESTRICTED);
    }

public static String resolveTemplateName(final ExecutedFragmentExpression executedFragmentExpression) {

        final Object templateNameObject = executedFragmentExpression.templateNameExpressionResult;
        if (templateNameObject == null) {
            // If template name expression result is null, we will execute the fragment on the "current" template
            return null;
        }
        final String evaluatedTemplateName = templateNameObject.toString();
        if (TEMPLATE_NAME_CURRENT_TEMPLATE.equals(evaluatedTemplateName)) {
            // Template name is "this" and therefore we are including a fragment from the same template.
            return null;
        }
        return templateNameObject.toString();

    }

public static Set<String> resolveFragments(final ExecutedFragmentExpression executedFragmentExpression) {

        final Object fragmentSelectorObject = executedFragmentExpression.fragmentSelectorExpressionResult;
        if (fragmentSelectorObject != null) {

            String fragmentSelector = fragmentSelectorObject.toString();

            if (fragmentSelector.length() > 3 &&
                    fragmentSelector.charAt(0) == '[' && fragmentSelector.charAt(fragmentSelector.length() - 1) == ']' &&
                    fragmentSelector.charAt(fragmentSelector.length() - 2) != '\'') {
                // For legacy compatibility reasons, we allow fragment DOM Selector expressions to be specified
                // between brackets. Just remove them.
                fragmentSelector = fragmentSelector.substring(1, fragmentSelector.length() - 1).trim();
            }

            if (fragmentSelector.trim().length() > 0) {
                return Collections.singleton(fragmentSelector);
            }

        }

        return null;

    }

